-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_texas; edit those, not this file.
-- Pure logic for the US State Names series (plans/square_state_names/PLAN.md): name normalization, climate
-- keys, town sampling, street and station picking. No game API here, so tests/<modId>/test_logic.lua covers
-- it offline. Plain Lua, pre-5.3 (no //, no bitwise operators, no utf8.*, no math.tointeger).
-- Loaded with require "square_names_us_texas::/square_names_us_texas/sn_logic.lua" by names.script.lua and rename.script.lua.

local M = {}

---------------------------------------------------------------------------
-- Names

-- UTF-8 letters folded to ASCII before comparing ("Café" == "cafe", "Utqiaġvik" == "utqiagvik"): the two-byte
-- Latin-1 letters (lead byte \195) and Latin Extended-A (U+0100-U+017F, lead bytes \196 and \197).
