--- Lowercase, accents folded, apostrophes dropped, every other run of punctuation/space -> one space, trimmed.
--- Apostrophes: ' and the UTF-8 right/left single quotes (U+2019, U+2018) and the Hawaiian okina (U+02BB).
function M.normalize(s)
	if type(s) ~= "string" then return "" end
	s = s:gsub("\226\128[\152\153]", ""):gsub("\202\187", ""):gsub("'", "")
	s = s:gsub("[\195-\197][\128-\191]", function(c) return FOLD[c] or c end)
	-- ASCII classes only: string.lower and %w follow the C locale, which may treat bytes >= 128 as letters.
	s = s:lower()
	s = s:gsub("[^0-9a-z#]+", " ")
	s = s:gsub("^%s+", ""):gsub("%s+$", "")
	return s
end

-- Suffixes the engine adds to keep names unique (binary strings around name_util.cpp), plus "station".
local TAIL_WORDS = { "east", "north", "west", "south", "annex", "branch", "central", "exchange", "halt", "sidings",
	"transfer", "station" }
local TAILS = {}
for i, w in ipairs(TAIL_WORDS) do TAILS[i] = " " .. w end

--- Normalized name without the engine's uniqueness suffixes: "Pike Street East" -> "pike street",
--- "King Street Station" -> "king street", "Upper Pike Street #2" -> "pike street".
function M.baseName(s)
	return M.baseOfNormalized(M.normalize(s))
end

--- baseName for a string that is already normalized (saves a second normalize in addUsed).
function M.baseOfNormalized(n)
	local changed = true
	while changed do
		changed = false
		local stripped = n:gsub(" stop #%d+$", ""):gsub(" #%d+$", "")
		if stripped ~= n then n, changed = stripped, true end
		for _, tail in ipairs(TAILS) do
			if #n > #tail and n:sub(-#tail) == tail then
				n, changed = n:sub(1, #n - #tail), true
				break
			end
		end
		local lead = n:match("^upper (.+)$") or n:match("^lower (.+)$")
		if lead then n, changed = lead, true end
	end
	return n
end

--- A set of names in use: exact (normalized) and base (without suffixes).
function M.newUsed(names)
	local u = { exact = {}, base = {} }
	for _, n in ipairs(names or {}) do M.addUsed(u, n) end
	return u
end

function M.addUsed(u, name)
	if type(name) ~= "string" or name == "" then return end
	local n = M.normalize(name)
	u.exact[n] = true
	u.base[M.baseOfNormalized(n)] = true
end

---------------------------------------------------------------------------
-- Climate

--- "::/climates/dry/dry.clima" -> "dry"; "dry" -> "dry"; nil/"" -> nil.
function M.climateKey(climate)
	if type(climate) ~= "string" or climate == "" then return nil end
	local last = climate:match("([^/:]+)$") or climate
	last = last:gsub("%.clima$", ""):gsub("%.lua$", "")
	if last == "" then return nil end
	return last:lower()
end

--- Tag weights for a climate from the state data, or nil (whole state) for unknown/missing climates.
function M.climateWeights(stateData, climate)
	local key = M.climateKey(climate)
	if key == nil or type(stateData) ~= "table" or type(stateData.climates) ~= "table" then return nil end
	return stateData.climates[key]
end

--- Equal weights over a regional set's tags (option C sets).
function M.regionWeights(tags)
	if type(tags) ~= "table" or #tags == 0 then return nil end
	local w = {}
	for _, t in ipairs(tags) do w[t] = 1 end
	return w
end

---------------------------------------------------------------------------
-- Towns

--- Selection weight from population: bigger places are more likely.
function M.tierWeight(pop)
	pop = tonumber(pop) or 0
	if pop >= 100000 then return 10 end
	if pop >= 30000 then return 6 end
	if pop >= 10000 then return 4 end
	if pop >= 3000 then return 2 end
	return 1
end

-- Guaranteed big towns: the TOP_BIG largest that fit always, the rest of the fitting big towns at random,
-- together at most BIG_SHARE of the requested towns (so small maps still vary).
M.TOP_BIG = 3
M.BIG_SHARE = 0.5
-- Probe 3 (2026-10-08): town sizes on the map don't follow name order (Seattle, 1st name, initialCap 94;
-- the 9th name 335). So big towns first doesn't make them big; it's harmless and kept only for a stable order.
-- Never claim "big cities get the big towns" in the description.
M.BIG_FIRST = true

local function hasTag(town, tag)
	for _, t in ipairs(town.t) do
		if t == tag then return true end
	end
	return false
end

--- Picks one index from `idx` (list of town indices) weighted by tier; nil when idx is empty.
local function pickWeighted(towns, idx, rng)
	local total = 0
	for _, i in ipairs(idx) do total = total + M.tierWeight(towns[i].p) end
	if total <= 0 then return nil end
	local r = rng() * total
	for _, i in ipairs(idx) do
		r = r - M.tierWeight(towns[i].p)
		if r < 0 then return i end
	end
	return idx[#idx]
end

local function unchosen(towns, chosen, pred)
	local out = {}
	for i, t in ipairs(towns) do
		if not chosen[i] and pred(t) then out[#out + 1] = i end
	end
	return out
end

--- Sorted list of tags with a positive weight (deterministic order for reproducible tests).
local function positiveTags(weights)
	local out = {}
	for tag, w in pairs(weights) do
		if type(w) == "number" and w > 0 then out[#out + 1] = tag end
	end
	table.sort(out)
	return out
end

--- Town names for a new game.
--- towns: list of { n = name, t = {tags}, p = population } (data order: population descending)
--- num: names wanted (< 0: all names); weights: tag -> weight (0 = top-up only) or nil for the whole state;
--- rng: function returning a float in [0, 1) (default math.random).
--- No duplicates until the data runs out; then repeats (like the base script).
function M.sampleTowns(towns, num, weights, rng)
	rng = rng or math.random
	local res = {}
	if num == nil or num < 0 then
		for _, t in ipairs(towns) do res[#res + 1] = t.n end
		return res
	end
	if num == 0 or #towns == 0 then return res end
	local chosen = {}
	local function take(i)
		chosen[i] = true
		res[#res + 1] = towns[i].n
	end

	-- 1. Guaranteed big towns. With weights: only those carrying a top-weighted tag of the climate.
	local maxW = 0
	if weights then
		for _, w in pairs(weights) do
			if type(w) == "number" and w > maxW then maxW = w end
		end
	end
	local function fitsBig(t)
		if not hasTag(t, "big") then return false end
		if not weights then return true end
		for _, tag in ipairs(t.t) do
			if maxW > 0 and weights[tag] == maxW then return true end
		end
		return false
	end
	local big = unchosen(towns, chosen, fitsBig)
	table.sort(big, function(a, b) return (towns[a].p or 0) > (towns[b].p or 0) end)
	local cap = math.max(math.min(M.TOP_BIG, num), math.floor(num * M.BIG_SHARE + 0.5))
	cap = math.min(cap, #big, num)
	local picked = {}
	for k = 1, math.min(M.TOP_BIG, cap) do picked[#picked + 1] = big[k] end
	local rest = {}
	for k = M.TOP_BIG + 1, #big do rest[#rest + 1] = big[k] end
	while #picked < cap and #rest > 0 do
		local j = math.floor(rng() * #rest) + 1
		if j > #rest then j = #rest end
		picked[#picked + 1] = table.remove(rest, j)
	end
	if M.BIG_FIRST then
		table.sort(picked, function(a, b) return (towns[a].p or 0) > (towns[b].p or 0) end)
	end
	for _, i in ipairs(picked) do take(i) end

	-- 2. Weighted by tag, then tier.
	if weights then
		local tags = positiveTags(weights)
		while #res < num do
			local pools, total = {}, 0
			for _, tag in ipairs(tags) do
				local idx = unchosen(towns, chosen, function(t) return hasTag(t, tag) end)
				if #idx > 0 then
					pools[#pools + 1] = { w = weights[tag], idx = idx }
					total = total + weights[tag]
				end
			end
			if #pools == 0 then break end
			local r = rng() * total
			local pool = pools[#pools]
			for _, p in ipairs(pools) do
				r = r - p.w
				if r < 0 then
					pool = p
					break
				end
			end
			take(pickWeighted(towns, pool.idx, rng))
		end
		-- 3a. Top-up from the weight-0 tags.
		while #res < num do
			local idx = unchosen(towns, chosen, function(t)
				for _, tag in ipairs(t.t) do
					if weights[tag] == 0 then return true end
				end
				return false
			end)
			if #idx == 0 then break end
			take(pickWeighted(towns, idx, rng))
		end
	end
	-- 3b. Top-up from the whole state (also the no-climate path).
	while #res < num do
		local idx = unchosen(towns, chosen, function() return true end)
		if #idx == 0 then break end
		take(pickWeighted(towns, idx, rng))
	end
	-- 4. Out of towns: repeats.
	while #res < num do
		local j = math.floor(rng() * #towns) + 1
		if j > #towns then j = #towns end
		res[#res + 1] = towns[j].n
	end
	return res
end

--- Every distinct town a weights table can ever yield before repeats (lint: pool sizes per climate).
function M.poolSize(towns, weights)
	if not weights then return #towns end
	local n = 0
	for _, t in ipairs(towns) do
		for _, tag in ipairs(t.t) do
			if weights[tag] ~= nil then
				n = n + 1
				break
			end
		end
	end
	return n
end

---------------------------------------------------------------------------
-- Streets and stations

--- Shuffled copy (Fisher-Yates); rng(m) returns an integer in [1, m] (default math.random).
function M.shuffle(list, rng)
	rng = rng or math.random
	local s = {}
	for i = 1, #list do s[i] = list[i] end
	for i = #s, 2, -1 do
		local j = rng(i)
		s[i], s[j] = s[j], s[i]
	end
	return s
end

local cityIndexCache = setmetatable({}, { __mode = "k" })

--- City entry for a town name (key or alias, compared normalized), or nil.
function M.findCity(cities, townName)
	if type(cities) ~= "table" or type(townName) ~= "string" then return nil end
	local index = cityIndexCache[cities]
	if index == nil then
		index = {}
		for key, entry in pairs(cities) do
			index[M.normalize(key)] = entry
			for _, alias in ipairs(entry.aliases or {}) do index[M.normalize(alias)] = entry end
		end
		cityIndexCache[cities] = index
	end
	return index[M.normalize(townName)]
end

-- Uniqueness suffixes for streets once a city's list is used up, in the engine's own style.
M.STREET_SUFFIXES = { " East", " West", " North", " South" }

--- The first street of `streets` whose base name nobody uses yet; then "<street> East/West/..." and
--- "<street> #n" (exact names). nil only for an empty list.
function M.pickStreet(streets, used)
	if type(streets) ~= "table" or #streets == 0 then return nil end
	for _, s in ipairs(streets) do
		if not used.base[M.baseName(s)] then return s end
	end
	for _, suf in ipairs(M.STREET_SUFFIXES) do
		for _, s in ipairs(streets) do
			local name = s .. suf
			if not used.exact[M.normalize(name)] then return name end
		end
	end
	for n = 2, 999 do
		for _, s in ipairs(streets) do
			local name = s .. " #" .. n
			if not used.exact[M.normalize(name)] then return name end
		end
	end
	return nil
end

--- The first station name of `list` whose base name nobody uses yet, or nil (leave the default name).
function M.pickStation(list, used)
	if type(list) ~= "table" then return nil end
	for _, s in ipairs(list) do
		if not used.base[M.baseName(s)] then return s end
	end
	return nil
end

--- Station kind -> list key in cities.lua.
M.KIND_LIST = { rail = "rail", street = "neighborhoods", airport = "airport", harbor = "harbor" }

function M.stationList(city, kind)
	local key = M.KIND_LIST[kind]
	if key == nil or type(city) ~= "table" then return nil end
	return city[key]
end

-- The one place that decides how a station name is written to the station group.
-- TODO(Probe 3 step 4): Probe 3 shows whether the game displays a construction station's group "King Street"
-- as "King Street Station". If it does NOT, set rail = " Station" here (rail names in cities.lua are stored
-- without "Station"). Airports and harbours are stored with their full names; bus/tram stations use plain
-- neighbourhood names. A state can override per kind with stationSuffix in its state.lua.
M.STATION_SUFFIX = { rail = "", street = "", airport = "", harbor = "" }

function M.stationName(kind, base, override)
	if type(base) ~= "string" or base == "" then return nil end
	local suffix = M.STATION_SUFFIX[kind] or ""
	if type(override) == "table" and type(override[kind]) == "string" then suffix = override[kind] end
	if suffix ~= "" and M.normalize(base):sub(-#M.normalize(suffix)) == M.normalize(suffix) then return base end
	return base .. suffix
end

--- Station kind from a construction's file name (base game layout), or nil for anything we don't rename
--- (helipads/heliports, depots, industries, mod constructions elsewhere).
function M.kindOfFile(fileName)
	if type(fileName) ~= "string" then return nil end
	local f = fileName:lower()
	if f:find("stations/rail/", 1, true) then return "rail" end
	if f:find("stations/air/", 1, true) then
		if f:find("heli", 1, true) then return nil end
		return "airport"
	end
	if f:find("stations/water/", 1, true) then return "harbor" end
	if f:find("stations/street/", 1, true) then return "street" end
	return nil
end

---------------------------------------------------------------------------
-- Params and ownership

--- ComboBox "On"/"Off" (numbers 1.0/0.0). The game passes the 1-based index (docs/findings.md); also accept
--- the number itself. nil (param missing) = On.
function M.paramOn(v)
	local n = tonumber(v)
	if n == nil then return true end
	return not (n == 2 or n == 0)
end

--- Several state mods active: the one whose name set the game uses renames everything; if the game uses another
--- state mod's set, this one stays idle. Base or third-party sets: every state mod renames its own cities.
function M.isActive(nameList, modId)
	if type(nameList) ~= "string" then return true end
	if nameList:sub(1, #"square_names_us_") ~= "square_names_us_" then return true end
	return nameList:sub(1, #modId + 2) == modId .. "::"
end

--- Shared city names between series mods (G9). contested = data/contested.lua: normalized city name (cities.lua
--- key or alias) -> modId of the bigger city's mod, generated across every state. false when this mod lost the
--- name to another mod that is active (activeMods = getModParams(), keyed by modId) and the game doesn't use
--- this mod's own name set (with its own set, this mod renames every city it knows).
function M.cityAllowed(contested, townName, modId, activeMods, nameList)
	if type(contested) ~= "table" or type(townName) ~= "string" then return true end
	local winner = contested[M.normalize(townName)]
	if type(winner) ~= "string" or winner == modId then return true end
	if type(nameList) == "string" and nameList:sub(1, #modId + 2) == modId .. "::" then return true end
	return not (type(activeMods) == "table" and activeMods[winner] ~= nil)
end

return M
